 function decorate({container,record,sha,sheet=''}){if(!container?.ownerDocument)return{reuse:0,auto:0};const D=container.ownerDocument;for(const n of container.querySelectorAll('[data-governance-provenance]')){n.classList.remove('pw-provenance-reuse','pw-provenance-auto','pw-provenance-manual');n.removeAttribute('data-governance-provenance');n.removeAttribute('data-provenance-label');if(own(n.dataset,'provenanceOriginalTitle')){n.title=n.dataset.provenanceOriginalTitle;delete n.dataset.provenanceOriginalTitle;}if(own(n.dataset,'provenanceOriginalDescription')){const old=n.dataset.provenanceOriginalDescription;if(old)n.setAttribute('aria-description',old);else n.removeAttribute('aria-description');delete n.dataset.provenanceOriginalDescription;}}container.querySelector(':scope > .pw-provenance-legend')?.remove();const counts={reuse:0,auto:0};for(const [kind,source]of [['auto','autoFillProvenance'],['reuse','workpaperReuseProvenance']])for(const p of entries(record,source)){if(p.sha256!==sha||(p.sheet||'')!==sheet)continue;const nodes=[...container.querySelectorAll('[data-cell],[data-native-word-id],[data-answer-id]')].filter(n=>n.dataset.cell===p.key||n.dataset.answerId===p.key||'native:'+n.dataset.nativeWordId===p.key);for(const node of nodes){const marked=node.closest('td')||node;if(!own(marked.dataset,'provenanceOriginalTitle')){marked.dataset.provenanceOriginalTitle=marked.title||'';marked.dataset.provenanceOriginalDescription=marked.getAttribute('aria-description')||'';}const manual=p.state==='manual-corrected',label=(manual?'人工修正 · ':kind==='reuse'?'同业复用 · ':'自动带入 · ')+'待复核';marked.dataset.governanceProvenance=kind;marked.dataset.provenanceLabel=label;if(kind==='reuse')marked.classList.remove('pw-provenance-auto');marked.classList.add('pw-provenance-'+kind);if(manual)marked.classList.add('pw-provenance-manual');marked.title=(marked.dataset.provenanceOriginalTitle?marked.dataset.provenanceOriginalTitle+'\n':'')+label+'；原始来源信息仍保留。';marked.setAttribute('aria-description',label+'，原始来源信息仍保留。');counts[kind]++;}}if(counts.reuse||counts.auto){const legend=D.createElement('p');legend.className='pw-provenance-legend';legend.textContent='来源提示：蓝色为同业通用文字复用（'+counts.reuse+'处），淡黄为资料自动带入（'+counts.auto+'处）；均待人工复核。人工修正后仍保留原始来源，不自动核对或冻结。';container.append(legend);}return counts;}
 function mount(host,adapter={}){if(!host?.ownerDocument)fail('治理面板需要有效容器。');const D=host.ownerDocument,el=(tag,text)=>{const n=D.createElement(tag);if(text!==undefined)n.textContent=text;return n;};let alive=true,busy=false,message='';function render(){if(!alive)return;const record=adapter.getRecord?.();const card=el('section');card.className='pw-governance';card.append(el('h3','本机核对冻结与同业通用模板'),el('p','人工点击核对完成后，仅冻结当前本机已保存的原表版本、填写与目录选择；不是审计意见、全目录完成或服务端不可篡改。设备管理员仍可能改动本机资料，请另行下载备份。'));if(!record){card.append(el('p','请先选择正式项目或独立试用。'));host.replaceChildren(card);return;}const label=el('label','行业标签（人工填写，同业精确匹配）'),input=el('input');input.type='text';input.maxLength=80;input.value=record.industryTag||'';input.dataset.governanceIndustry='';input.disabled=busy;label.append(input);const save=el('button','保存行业标签');save.type='button';save.className='btn';save.disabled=busy||typeof adapter.onSaveIndustry!=='function';save.onclick=async()=>{if(busy)return;try{busy=true;await adapter.onSaveIndustry(input.value.trim());message='已保存人工行业标签。';}catch(e){message=typeof e?.message==='string'?e.message:'行业标签未保存。';}finally{busy=false;render();}};card.append(label,save,el('p','复用仅限原目录第一、第二部分，并须人工逐项批准通用文字；不默认全选，不跨公司复制金额、客户事实、风险判断或签字。蓝色内容仍待复核。'));const list=el('ul');for(const lock of Object.values(locks(record))){const li=el('li',(lock.index||lock.row)+' · '+(lock.name||'底稿')+'：已核对冻结 · '+(lock.reviewer?.name||'')+' · '+(lock.reviewedAt||''));const download=el('button','下载该冻结快照');download.type='button';download.className='btn';download.disabled=typeof adapter.onExportSnapshot!=='function';download.onclick=()=>adapter.onExportSnapshot?.(copy(lock));li.append(download);list.append(li);}if(!list.children.length)list.append(el('li','尚无核对冻结记录；填写覆盖率不会自动触发冻结。'));card.append(list);if(typeof adapter.onExportBackup==='function'){const b=el('button','下载本项目治理与填写备份');b.type='button';b.className='btn';b.onclick=()=>adapter.onExportBackup();card.append(b);}if(typeof adapter.openReuse==='function'){const b=el('button','选择同业通用文字（逐项确认）');b.type='button';b.className='btn';b.onclick=()=>adapter.openReuse();card.append(b);}const status=el('p',message);status.setAttribute('role','status');card.append(status);host.replaceChildren(card);}render();return Object.freeze({refresh:render,destroy(){alive=false;host.replaceChildren();}});}
 return Object.freeze({createLock,assertTransition,isLocked,verifyLock,asyncHash,canonical,approveTemplate,previewReuse,applyReuse,noteManualEdit,decorate,mount,provenanceKey,policy:POLICY});
